import type { RootState } from "../../redux/store"
import { useDispatch, useSelector } from "react-redux"
import { type AppDispatch } from "../../redux/store";
import { useEffect, useState } from "react";
import type { UserLogin, UserLoginError } from "../../types/type";
import { login } from "../../redux/authslice";
import { useNavigate } from "react-router-dom";
import { Link } from "react-router-dom";




const Login:React.FC=()=>{
    const {isLoading,redirectHome}=useSelector((state:RootState)=>state.auth);
    const dispatch=useDispatch<AppDispatch>();
    const navigate=useNavigate();
    const [user,setUser]=useState<UserLogin>({
        email:"",
        password:"",
    })
    const [error,setError]=useState<UserLoginError>({});
    const validation=()=>{
        let error:UserLoginError={};
        if(!user.email) error.email="please enter your email";
        if(!user.password)error.password="please enter your password";
        return error;
    }
    const postUserData = (e: React.ChangeEvent<HTMLInputElement>) => {
        const fieldName = e.target.name;
        const fieldValue = e.target.value;

        if (fieldName === "email") {
            if (fieldValue.trim().length === 0) {
                setUser({ ...user, email: "" });
                setError({ ...error, email: "Please enter your email in this inputfield" });
            } else {
                setUser({ ...user, email: fieldValue });
                setError({ ...error, email: "" });
            }
        }
        if (fieldName === "password") {
            if (fieldValue.trim().length === 0) {
                setUser({ ...user, password: "" });
                setError({ ...error, password: "Please enter your password in this inputfield" });
            } else {
                setUser({ ...user, password: fieldValue });
                setError({ ...error, password: "" });
            }
        }
    };

    const handleSubmit = (e: React.SyntheticEvent) => {
        e.preventDefault();
        const errors = validation();
        setError(errors);
        if (Object.keys(errors).length > 0) return null;
        let data = {
            email: user.email,
            password: user.password
        };
        dispatch(login(data));
    };


    useEffect(() => {
        const token = localStorage.getItem("token") || sessionStorage.getItem("token");
        const loginPage = window.location.pathname.toLowerCase() === "/login";
        if (token && loginPage) navigate("/");

    }, [navigate, redirectHome]);

    return (
        <>
            <div className="grow min-h-[calc(100vh-140px)] flex items-center justify-center bg-slate-950 p-6 relative overflow-hidden">
                {/* Vibrant Background Glow Orbs */}
                <div className="absolute top-1/4 -left-20 w-96 h-96 bg-pink-600/25 rounded-full blur-[140px] pointer-events-none"></div>
                <div className="absolute bottom-1/4 -right-20 w-96 h-96 bg-indigo-600/25 rounded-full blur-[140px] pointer-events-none"></div>

                {/* Glass Container */}
                <div className="glass-card p-10 rounded-3xl shadow-[0_15px_50px_rgba(0,0,0,0.5)] w-full max-w-md z-10 relative overflow-hidden backdrop-blur-2xl">
                    <div className="absolute -top-24 -right-24 w-48 h-48 bg-gradient-to-br from-pink-500/20 to-purple-500/0 rounded-full blur-2xl pointer-events-none"></div>

                    {/* Header */}
                    <div className="text-center mb-8">
                        <div className="inline-flex items-center justify-center w-12 h-12 rounded-2xl bg-gradient-to-tr from-pink-500 via-purple-600 to-indigo-600 text-white font-black text-2xl shadow-lg shadow-pink-500/30 mb-4">
                            S
                        </div>
                        <h2 className="text-3xl font-black text-white tracking-tight">Welcome Back</h2>
                        <p className="text-slate-400 text-sm mt-2">
                            New here?{" "}
                            <Link to="/register" className="text-pink-400 font-bold hover:text-pink-300 transition underline underline-offset-4 decoration-pink-500/40">
                                Create an account
                            </Link>
                        </p>
                    </div>

                    <form onSubmit={handleSubmit} noValidate className="space-y-6">
                        {/* Email Field */}
                        <div className="relative">
                            <label className="block text-xs font-bold uppercase tracking-wider text-slate-300 mb-2 ml-1">Email Address</label>
                            <input 
                                type="email" name="email" value={user.email} onChange={(e) => postUserData(e)} 
                                className="glass-input w-full px-4 py-3.5 rounded-xl text-white placeholder-slate-500 focus:outline-none transition duration-300 text-sm font-medium" 
                                placeholder="name@example.com" required 
                            />
                            {error.email && <p className="text-xs text-rose-400 font-semibold mt-1.5 ml-1 flex items-center gap-1"><span>⚠</span> {error.email}</p>}
                        </div>

                        {/* Password Field */}
                        <div className="relative">
                            <div className="flex justify-between items-center mb-2 ml-1">
                                <label className="block text-xs font-bold uppercase tracking-wider text-slate-300">Password</label>
                                <Link to="/forget" className="text-xs text-pink-400 hover:text-pink-300 font-bold transition">
                                    Forgot Password?
                                </Link>
                            </div>
                            <input 
                                type="password" name="password" value={user.password} onChange={(e) => postUserData(e)} 
                                className="glass-input w-full px-4 py-3.5 rounded-xl text-white placeholder-slate-500 focus:outline-none transition duration-300 text-sm font-medium" 
                                placeholder="••••••••" required 
                            />
                            {error.password && <p className="text-xs text-rose-400 font-semibold mt-1.5 ml-1 flex items-center gap-1"><span>⚠</span> {error.password}</p>}
                        </div>

                        {/* Submit Button */}
                        <button 
                            type="submit" 
                            className="w-full bg-gradient-to-r from-pink-600 via-purple-600 to-indigo-600 hover:from-pink-500 hover:to-indigo-500 text-white font-black py-4 rounded-xl shadow-lg shadow-pink-600/30 transition-all duration-300 active:scale-[0.98] disabled:opacity-50 mt-2 text-sm uppercase tracking-widest" 
                            disabled={isLoading}
                        >
                            {isLoading ? (
                                <div className="flex items-center justify-center gap-3">
                                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                    <span>Verifying...</span>
                                </div>
                            ) : (
                                "Login to Dashboard"
                            )}
                        </button>
                    </form>

                    {/* Divider */}
                    <div className="relative my-8">
                        <div className="absolute inset-0 flex items-center"><span className="w-full border-t border-white/10"></span></div>
                        <div className="relative flex justify-center text-[10px] uppercase font-black tracking-widest"><span className="bg-slate-900/90 px-3 text-slate-500 rounded-full border border-white/5">Secure Access</span></div>
                    </div>
                </div>
            </div>

        </>
    )
}
export default Login;